dispatch_case:
// stable-diffusion.cpp diffusion-model dispatch. sefi_image has NO Runner of its own:
// upstream builds it through the SAME path as flux2 (Flux::FluxRunner + LLMEmbedder).
// Simplest correct integration is to MERGE sefi into the existing fork flux2 branch condition,
// i.e. change the fork line
//     } else if (sd_version_is_flux2(version)) {
// to
//     } else if (sd_version_is_flux2(version) || sd_version_is_sefi_image(version)) {
// The body below is already exactly the fork's flux2 body (backend_for + params_backend_for,
// NO model_manager); reproduced here verbatim so it can also be pasted as a standalone else-if:
} else if (sd_version_is_sefi_image(version)) {
    bool is_chroma   = false;
    cond_stage_model = std::make_shared<LLMEmbedder>(backend_for(SDBackendModule::TE),
                                                     params_backend_for(SDBackendModule::TE),
                                                     tensor_storage_map,
                                                     version);
    diffusion_model  = std::make_shared<Flux::FluxRunner>(backend_for(SDBackendModule::DIFFUSION),
                                                         params_backend_for(SDBackendModule::DIFFUSION),
                                                         tensor_storage_map,
                                                         "model.diffusion_model",
                                                         version,
                                                         sd_ctx_params->chroma_use_dit_mask);
}

